<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue';
import { api } from '../../api/client';
import type { components } from '../../api/generated/admin';
import { consumerDate } from './consumer-format';
type Plan=components['schemas']['ConsumerPlan'];
defineProps<{users:components['schemas']['User'][];groups:components['schemas']['Group'][]}>();const emit=defineEmits<{changed:[]}>();
const plans=ref<Plan[]>([]),error=ref(''),message=ref(''),busy=ref(false),userID=ref(''),planID=ref(''),days=ref(0);
const initial=()=>({id:'',name:'',group_id:'',enabled:true,days:30,max_concurrency:5,budget:{max_requests:0,max_tokens:0,max_usd:0},period:'month' as Plan['period']});
const draft=reactive(initial());async function load(){plans.value=(await api('/admin/api/consumer/plans')).plans;}
async function run(fn:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';message.value='';try{await fn();message.value='已保存';await load();emit('changed');}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
function save(){return run(async()=>{await api('/admin/api/consumer/plans',{method:'POST',body:draft});Object.assign(draft,initial());});}
function assign(action:string){return run(async()=>{await api('/admin/api/consumer/subscription',{method:'POST',body:{user_id:userID.value,plan_id:planID.value,action,days:days.value}});});}
onMounted(()=>load().catch(e=>error.value=(e as Error).message));
</script>
<template>
<div class="consumer-form"><h3>套餐模板</h3><p class="hint">模板修改只影响新分配；同套餐续期延长有效期并保留已用额度。到期、停用后新请求被拒绝。</p>
<form @submit.prevent="save"><div class="field-grid cols-2"><div class="field"><label>套餐名称<input v-model="draft.name" required maxlength="120"></label></div><div class="field"><label for="ConsumerPlansSelect1">分组</label><select id="ConsumerPlansSelect1" v-model="draft.group_id" required><option disabled value="">选择分组</option><option v-for="g in groups" :key="g.id" :value="g.id">{{g.name}}</option></select></div><div class="field"><label>有效天数<input v-model.number="draft.days" type="number" min="1" max="3650" required></label></div><div class="field"><label>并发上限（0 不限）<input v-model.number="draft.max_concurrency" type="number" min="0" max="1024" required></label></div><div class="field"><label for="ConsumerPlansSelect2">额度周期</label><select id="ConsumerPlansSelect2" v-model="draft.period"><option value="lifetime">订阅总量</option><option value="day">每日 UTC</option><option value="week">每周 UTC</option><option value="month">每月 UTC</option></select></div><div class="field"><label>请求次数（0 不限）<input v-model.number="draft.budget.max_requests" type="number" min="0" required></label></div><div class="field"><label>Token（0 不限）<input v-model.number="draft.budget.max_tokens" type="number" min="0" required></label></div><div class="field"><label>参考 USD（0 不限）<input v-model.number="draft.budget.max_usd" type="number" min="0" step="any" required></label></div></div><label class="check"><input v-model="draft.enabled" type="checkbox">允许分配 / 兑换</label><div class="actions"><button class="btn primary" :disabled="busy">保存套餐</button><button type="button" class="btn" @click="Object.assign(draft,initial())">新建模板</button></div></form>
<div class="table-wrap"><table><thead><tr><th>套餐</th><th>有效期</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="p in plans" :key="p.id"><td>{{p.name}}</td><td>{{p.days}} 天</td><td>{{p.enabled?'启用':'停用'}}</td><td><button class="btn xs" @click="Object.assign(draft,{...p,budget:{...p.budget}})">编辑模板</button></td></tr></tbody></table></div>
<h3>分配与续期</h3><div class="actions"><select v-model="userID" aria-label="订阅用户"><option value="" disabled>选择用户</option><option v-for="u in users" :key="u.id" :value="u.id">{{u.username}} · {{u.subscription.id?(u.subscription.disabled?'停用':consumerDate(u.subscription.expires_at)):'无订阅'}}</option></select><select v-model="planID" aria-label="分配套餐"><option value="" disabled>选择套餐</option><option v-for="p in plans.filter(x=>x.enabled)" :key="p.id" :value="p.id">{{p.name}}</option></select><input v-model.number="days" type="number" min="0" max="3650" aria-label="续期天数" placeholder="0 使用套餐天数"></div>
<div class="actions"><button class="btn primary" :disabled="busy||!userID||!planID" @click="assign('assign')">分配 / 续期</button><button class="btn" :disabled="busy||!userID" @click="assign('disable')">停用订阅</button><button class="btn" :disabled="busy||!userID" @click="assign('enable')">恢复订阅</button><button class="btn danger" :disabled="busy||!userID" @click="assign('remove')">移除订阅限制</button></div><p class="hint">一个用户仅有一个生效订阅。分配时全部用户密钥跟随套餐分组；移除订阅后保留分组，恢复原有用户预算规则。</p>
<p v-if="error" class="err-text" role="alert">{{error}}</p><p v-if="message" role="status">{{message}}</p></div>
</template>
